$DEV = 'C:\Users\eric_rash\Desktop\DEV'
$skip = @('.claude','_tools','_DRIVE','token-dashboard','_ARCHIVE','Football','SpecialRequests','.git')
$dirs = @()
$dirs += Get-ChildItem $DEV -Directory -Force
foreach ($g in 'Football','SpecialRequests') {
  if (Test-Path "$DEV\$g") { $dirs += Get-ChildItem "$DEV\$g" -Directory -Force }
}
$rows = foreach ($d in $dirs) {
  if ($skip -contains $d.Name -and ($d.Parent.FullName -eq $DEV)) { continue }
  if ($d.Name -like '*_OLD_merged*' -or $d.Name -eq '.git' -or $d.Name -eq '.claude') { continue }
  $rel = $d.FullName.Substring($DEV.Length + 1)
  if (-not (Test-Path (Join-Path $d.FullName '.git'))) {
    [pscustomobject]@{ path=$rel; kind='not-a-repo'; remote=''; branch=''; dirty=''; ahead='' }; continue
  }
  $p = $d.FullName
  $remote = (git -C $p remote get-url origin 2>$null)
  $branch = (git -C $p rev-parse --abbrev-ref HEAD 2>$null)
  $dirty = @(git -C $p status --porcelain 2>$null).Count
  $ahead = (git -C $p rev-list --count '@{u}..HEAD' 2>$null)
  if (-not $ahead) { $ahead = 'no-upstream' }
  $kind = if (-not $remote) { 'no-remote' } elseif ($remote -match 'erash11') { 'erash11' } else { 'other-remote' }
  [pscustomobject]@{ path=$rel; kind=$kind; remote=$remote; branch=$branch; dirty=$dirty; ahead=$ahead }
}
# DEV root thin repo
$rows += [pscustomobject]@{ path='(DEV root)'; kind='erash11'; remote=(git -C $DEV remote get-url origin); branch=(git -C $DEV rev-parse --abbrev-ref HEAD); dirty=@(git -C $DEV status --porcelain).Count; ahead=(git -C $DEV rev-list --count '@{u}..HEAD') }
$rows | Export-Csv "$PSScriptRoot\inventory.csv" -NoTypeInformation
"total: $($rows.Count)"
$rows | Group-Object kind | % { "$($_.Name): $($_.Count)" }
"--- attention (not clean erash11)"
$rows | ? { $_.kind -ne 'erash11' -or $_.dirty -ne 0 -or $_.ahead -ne '0' } | Format-Table path,kind,branch,dirty,ahead,remote -AutoSize | Out-String -Width 250

