$DEV = 'C:\Users\eric_rash\Desktop\DEV'
$rows = Import-Csv "$PSScriptRoot\inventory.csv" | ? { $_.kind -eq 'erash11' }
$out = foreach ($row in $rows) {
  $p = if ($row.path -eq '(DEV root)') { $DEV } else { Join-Path $DEV $row.path }
  $b = $row.branch
  $fetch = git -C $p fetch origin 2>&1
  $fetchOk = $LASTEXITCODE -eq 0
  $behind = git -C $p rev-list --count "HEAD..origin/$b" 2>$null
  $action = 'clean'; $note = ''
  if (-not $fetchOk) { $action = 'FETCH-FAILED'; $note = ($fetch | Select-Object -Last 1) }
  elseif ($behind -and [int]$behind -gt 0) {
    $m = git -C $p merge --no-edit "origin/$b" 2>&1
    if ($LASTEXITCODE -ne 0) {
      $action = 'CONFLICT'; $note = (git -C $p diff --name-only --diff-filter=U) -join ';'
      if (-not $note) { $note = ($m | Select-Object -Last 2) -join ' | ' }
    } else { $action = "pulled $behind" }
  }
  $ahead = git -C $p rev-list --count "origin/$b..HEAD" 2>$null
  if ($action -notmatch 'CONFLICT|FAILED' -and $ahead -and [int]$ahead -gt 0) {
    $push = git -C $p push 2>&1
    if ($LASTEXITCODE -ne 0) { $action += ' PUSH-FAILED'; $note = ($push | Select-Object -Last 1) } else { $action += " pushed $ahead" }
  }
  [pscustomobject]@{ path=$row.path; action=$action; note=$note }
}
$out | Export-Csv "$PSScriptRoot\sync.csv" -NoTypeInformation
$out | Group-Object { ($_.action -split ' ')[0] } | % { "$($_.Name): $($_.Count)" }
'--- non-clean'
$out | ? { $_.action -ne 'clean' } | Format-Table -AutoSize | Out-String -Width 250

